-- Coordinator class + Advanced Class (Choreographer, Coach, Designer, Groomer, Rising Star) Features,
-- extracted from the Player's Handbook PDF pages 44-59. Part of [[Add all Class features to the list]].
--
-- NOTE: the PDF's own level-summary table lists different names than the actual write-ups for 3
-- Coordinator base-class features -- the summary table calls them "Shining Light" (L4), "Idolized" (L5),
-- and "Command of the Stage" (L15), but the actual detailed sections are titled "Poised Instinct" (L4),
-- "Appearance" (L5), and "Star of the Show" (L15). This is an inconsistency within the source PDF
-- itself, not introduced here -- used the detailed write-up's name in each case since that's where the
-- real mechanical text lives, same as every other Feature in this migration.
--
-- Where a Feature references a move/item that's just a named catalog entry, only the name is given
-- (mechanics live in the existing `moves`/`items` tables, matching the established simplification
-- pattern) -- confirmed via grep that Designer's Item Builder/Item Manufacturer items already exist in
-- `20260808120000_items_held_items.sql`.
insert into features (name, description, class_id, subclass_id, level_required) values
  ('Put Your Hands in the Air', 'Coordinators are expected to be able to rouse a crowd and you’re able to get them going. 3/day, choose a Star Point category that you already are aware of and add your Special Defense or Speed modifier to an appeal that matches that Star Point category for that appeal’s Heart Point total, or as an action one of your Pokémon within 30ft of you uses the move Helping Hand', (select id from classes where name = 'Coordinator'), null, 1),
  ('Wonderous Applause', 'You’re not one to brag, but you’re quite good at giving people what they want and you’ve trained your Pokémon to do the same. 3/day, once per encounter/contest, you may have your Pokémon’s contest appeal have the Crowd Pleaser effect in addition to whatever effect it usually has, or as an action one of your Pokémon within 30ft of you uses the move Encore', (select id from classes where name = 'Coordinator'), null, 1),
  ('Favorite Festival', 'When it comes to contests, there is five different core styles to perform. You specialize in your choice of the following contest stats; Cool, Tough, Beauty, Clever, and Cute. Depending on your choice, Coordinator features will work in specific ways. When you get to level 7 and 11, you may choose another favorite contest attribute in addition to the one you chose at level 2. In addition, 3/day, as an action, grant one of your Pokémon within 30 ft a passive for 10 mins, chosen from: Cool - Inner Focus (immune to being Stunned); Tough - Big Pecks (Defense cannot be lowered by a foe’s effects); Beauty - Overcoat (immune to damage from weather); Clever - Own Tempo (immune to being Confused); Cute - Oblivious (immune to Infatuation). Special: many Coordinator features modify contest keywords for a move -- trainers can only add 1 more contest keyword to a move at a time, and this does not change the move’s initial base appeal. If a Coordinator uses a feature as an action that allows their Pokémon to use a particular move, their Pokémon will only be able to use that move during their next turn, and having that Pokémon take their turn will still require the Coordinator''s command as usual', (select id from classes where name = 'Coordinator'), null, 2),
  ('Stat Increase and Advanced Class', 'Choose two different Trainer Stats to increase by 1, then gain 1d4 max HP. You only gain new stats at levels 3, 7, and 11. Choose a Coordinator Advanced Class or a different base Class. You can only ever gain a single Class or Advanced Class at a time, at level 3, level 7, and level 11', (select id from classes where name = 'Coordinator'), null, 3),
  ('Poised Instinct', 'When getting up to the stage, a feeling overwhelms you and you know exactly how to impress those in front of you. 1/day, when a contest starts, you are secretly informed of one Star Point category that you do not know. Once you are level 11, you are secretly informed of two Star Point categories. Additionally, whenever you are rolling a Perception check you may add your Special Defense or Speed modifier to your result', (select id from classes where name = 'Coordinator'), null, 4),
  ('Appearance', 'Coordinators gain fame as they blaze a trail of victory, wearing an aura of charisma that spreads throughout their entourage. 3/day, when an ally next to you rolls a skill check for Bluff, Diplomacy, or Pokémon Handling, they may add your Special Defense or Speed modifier in addition to any other bonuses they may add', (select id from classes where name = 'Coordinator'), null, 5),
  ('Steal the Show', 'At the drop of a hat, you and your Pokémon can gather a crowd’s attention and perform various talents to entertain and amaze. 3/day, once per encounter/contest: after you make an appeal, all opponents whose appeal qualifies for a Star Point category that your appeal matches get –6 on their appeal that round whether they preformed before or after you that round; or as an action one of your Pokémon within 30ft of you uses the move Follow Me (this is your command). In addition, once per day you may hold the attention of everyone within 50ft of you while performing anywhere for X minutes where X is the sum of your Special Defense and Speed modifier. Allies are not affected by your antics and others may notice things happening around them with Perception skill checks', (select id from classes where name = 'Coordinator'), null, 6),
  ('Stat Increase and Advanced Class', 'Choose two different Trainer Stats to increase by 1, then gain 1d4 max HP. You only gain new stats at levels 3, 7, and 11. Choose a Coordinator Advanced Class or a different base Class. You can only ever gain a single Class or Advanced Class at a time, at level 3, level 7, and level 11', (select id from classes where name = 'Coordinator'), null, 7),
  ('Character Building', 'In order to raise the best contest Pokémon, having a healthy attitude for any given contest is key. Once per day, after spending two hours working with one of your Pokémon, you may change their nature depending on your chosen contest stats for your Favorite Festival feature, adjusting the Pokémon’s relevant stats when you do: Cool - Adamant, Brave, Lonely, or Naughty; Tough - Bold, Impish, Lax, or Relaxed; Beauty - Mild, Modest, Quiet, or Rash; Clever - Calm, Careful, Gentle, or Sassy; Cute - Hasty, Jolly, Naïve, or Timid. You cannot use this feature with the same Pokémon more than once per week', (select id from classes where name = 'Coordinator'), null, 8),
  ('Rehearsed Sequence', 'Practice makes perfect and your Pokémon’s combination moves shine on the stage. For each of your Pokémon''s moves, assign two as “Rehearsed.” 1/Contest, when Rehearsed moves are used consecutively over two rounds of appeal, add +2d4 to the second Rehearsed move. 3/day, during combat, when Rehearsed moves are used consecutively over two rounds of combat, if the second Rehearsed move is an attack it gains one of the following effects depending on the move’s Contest type: Cool - target’s Defense is -1 for 10 mins; Tough - target’s Attack is -1 for 10 mins; Beauty - target’s Special Defense is -1 for 10 mins; Clever - target’s Special Attack is -1 for 10 mins; Cute - target’s Speed is -1 for 10 mins', (select id from classes where name = 'Coordinator'), null, 9),
  ('It’s How You Carry Yourself', 'By spending time with each of your performers, you’ve taught each of them to display talents without displeasing a judge, even when off script during a contest. 3/day, once per contest, when making an appeal to a judge, you can choose to make your Pokémon’s appeal not lower voltage or to make your Pokémon’s appeal raise the voltage regardless of how the voltage would normally be affected. In addition, 3/day, as an action, grant one of your Pokémon within 30 ft a passive for 10 mins, chosen from: Cool - Defiant (if a foe lowers any of your stats, you have +2 Attack until your lowered stats are returned to normal); Tough - Battle Armor (critical hits are treated as normal hits against you); Beauty - Multiscale (when you are at Max HP, you take -4 damage from all attacks); Clever - Filter (super-effective attacks against you deal -1d12 damage); Cute - Cute Charm (whenever you are hit with a melee attack, roll 1d4; on 4, Infatuate the attacker)', (select id from classes where name = 'Coordinator'), null, 10),
  ('Stat Increase and Advanced Class', 'Choose two different Trainer Stats to increase by 1, then gain 1d4 max HP. You only gain new stats at levels 3, 7, and 11. Choose a Coordinator Advanced Class or a different base Class. You can only ever gain a single Class or Advanced Class at a time, at level 3, level 7, and level 11', (select id from classes where name = 'Coordinator'), null, 11),
  ('Poise, Serenity, Style', 'Just walking into a space can draw looks and you and your Pokémon know how to make a first impression. The first 2 times you roll a 1 during a contest appeals, reroll those dice. In addition, upon meeting someone new, you have a +2 to any Insight skill checks you make against them. In addition, 3/day, as an action, grant one of your Pokémon within 30 ft a passive for 10 mins, chosen from: Cool - Magician (when hitting with a melee attack, you steal the target’s held item, if any); Tough - No Guard (you cannot miss your attacks, and attacks made against you cannot miss); Beauty - Mirror Armor (if your stats would be lowered by a foe’s effects, instead that offender’s stat is lowered); Clever - Download (your Attack is +1 against targets with lower Defense than Special Defense, your Special Attack is +1 against targets with lower Special Defense than Defense); Cute - Disguise (the first time you are hit with an attack each encounter, the attack is negated)', (select id from classes where name = 'Coordinator'), null, 12),
  ('Breathtaking Flourish', 'By minimizing destructive battle capabilities and effort, you Pokémon can focus on the glamour of performing two moves simultaneously to woo judges and audience alike. Once per day, one of your Pokémon can perform two moves during the same appeal round and roll for both moves, adding them together for the appeal. In addition, after spending 10 hours with one of your Pokémon with at least 2 Contest Ribbons, you may teach it a move depending on your chosen contest stats: Cool - Pack Mon; Tough - Impenetrable Stance; Beauty - Absolutely Breathtaking; Clever - Language; Cute - Cutesy Coercion', (select id from classes where name = 'Coordinator'), null, 13),
  ('Contest Tutoring', 'Having seen and studied various moves that make a splash in contests you’ve figured out how to teach those moves to your Pokémon. Once per day, after spending three hours working with one of your Pokémon, you may teach a move that has a contest attribute matching one of your chosen contest stats for your Favorite Festival feature. Moves taught with the Contest Tutoring feature must still fit the Pokémon’s proficiencies. A Pokémon cannot benefit from Contest Tutoring more than once per week', (select id from classes where name = 'Coordinator'), null, 14),
  ('Star of the Show', 'There isn’t a person in the stadium who isn’t watching you perform, no matter what the event. 1/Contest, after the final appeal during a Contest, but before Star Points are awarded, choose a category for which a Star Point will be awarded. Your chosen category replaces a Star Point category of your GM’s choice that you do not know. If you know every category for which Star Points will be awarded, you may choose which category to replace. The category you choose may be a category that already is awarding a Star Point, meaning that two Star Points will be awarded for that criteria. In addition, during Pokémon battles, your Pokémon have +3 speed when deciding turn order if they have earned more contest ribbons than any enemy Pokémon. In addition, whenever you use a feature that temporarily grants a Pokémon a passive ability, you can use it to target an allied Pokémon instead of only being able to use it on your own Pokémon', (select id from classes where name = 'Coordinator'), null, 15),

  ('Base Routine', 'Your Pokémon move in rhythmic ways, gracefully making their way across the stage of battle. Whenever your Pokémon do not move their full distance during their turn in combat, they get +1 to their Defense, Special Defense, and Speed the next time they are targeted by an attack', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 1),
  ('Practicing Scales', 'You often sing with your Pokémon, as you try to teach them different basic melodies and sounds to make with their voices. When using attacks, your Pokémon’s move can be treated as if they are sound-based or not regardless of what they naturally are. In addition, once per day you may spend two hours with one of your Pokémon to teach them the move Soft Song', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 1),
  ('En Point', 'You and your Pokémon are not to be frazzled during battle, each step is graceful planned and executed. When you or your Pokémon do not move their full distance during their turn in combat, they cannot be Stunned or moved by a foe’s effects until their next turn', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 2),
  ('Attention to Me', 'Coordinators may be able to grab attention with their charms, but you perform like none other. Whenever you make a Perform skill check with that would involve either dance or your voice roll the check three times and use the best result', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 3),
  ('Gradual Rise', 'A well-choreographed performance with a gradual rise and climax will astound the audience and judges alike. If during each round of appeals, the Heart Points you earn are each consecutively higher than your previous score, gain 10d4 points after the final appeal. In addition, if your Pokémon would deal less damage during a round of combat than their previous turn during an attack, they may deal an additional +1d6 once per combat', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 4),
  ('Stage Presence', 'Often, judges will be particularly interested in your Pokémon’s appeal because they always seem to add a different flourish or lovely tune while doing so. 3/day, during an appeal, you may replace up to X d4 with d6, where X is your Special Defense or Speed modifier', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 6),
  ('Gentle Footfall', 'Poise is important while dancing and in as a byproduct of your training you’ve developed particularly silent footsteps. When making Stealth skill checks, you may roll twice and use the better result. In addition, whenever your Pokémon makes an attack against a foe from behind the foe’s line of sight and was not in the target’s line of sight during that turn, they may add +2 during their accuracy checks', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 7),
  ('Enthralling Voices', 'Your Pokémon command the attention of others in battle and even influence Pokémon to stop in place, getting lost in your Pokémon’s charms. 3/day, as an action, you add the effect, “On hit, the target is Infatuated,” to one of your Pokémon’s attacks that does not already have an effect during their next turn. In addition, during the appeal rounds in contests, Pokémon making an appeal immediately after your Pokémon in the same round do not roll one of their d4 for a single appeal unless they have already been affected by your Enthralling Voices feature during that contest', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 8),
  ('Dancing Dodge', 'The constant flow of battle has a rhythm of its own and you with your Pokémon can slide around attacks and problems. 1/day, if you would be hit by a Pokémon’s attack that only targeted you, you may dodge it. In addition, once per week you may spend 4 hours with once of your Pokémon to teach them the move Detect', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 10),
  ('As Rehearsed', 'Often you’ll spend time with your Pokémon going over their routines for a contest, and sticking to a script often has good payoffs. At the beginning of a contest, you may choose the moves your Pokémon will be performing during each round of appeals. If you do, your Pokémon’s appeals cannot be negatively affected by other contestant’s displays and once during the contest you may have a judge you are appealing to have their voltage raised once regardless of your appeal’s contest attribute', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 11),
  ('Elemental Flourish', 'When moving about passionately, you Pokémon may release energy from themselves that enhance their performances. 3/day, as an action, you may have your Pokémon’s normal-type move change its type to match one of its types until the end of combat. In addition, once per contest you may have one of your Pokémon’s move change its attribute into a different contest attribute of your choice (Beauty, Clever, Cool, Cute, Tough)', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 12),
  ('Dazzling the Stage', 'Your Pokémon’s appeals are stunning and when perfectly executed your Pokémon’s performances destroy anyone else’s chance at winning. Before rolling your dice during any appeal choose a number. If your result for Heart Points during that appeal matches the chosen number, double the value of your appeal during that round', (select class_id from subclasses where name = 'Choreographer'), (select id from subclasses where name = 'Choreographer'), 13),

  ('Faster', 'Kick it up! Really lean into it! Your cheers push your Pokémon to go faster and faster when it matters. 3/day, as an action, one of your Pokémon within 25 ft gets a temporary bonus to its movement speed. The bonus is equal to 5 feet multiplied by your Speed or Special Defense modifier, and lasts 5 minutes', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 1),
  ('Stronger', 'You’ve got this! Push harder! Your encouragement pushes some extra strength into your Pokémon’s efforts. 3/day, as an action, your Pokémon within 25ft are twice as strong and can move objects larger than itself as if they were the same size as them, for the next 5 mins. In addition, those Pokémon deal X more damage when attacking with an Attack stat move (where X is your Special Defense or Speed modifier). Additionally, if there is a dummy during a contest to attack on stage, your Pokémon deal +4 damage to the dummy during their appeals', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 1),
  ('Work It', 'This is nothing new! Get it done! Your direction helps your Pokémon overcome obstacles without issue. 3/day, as an action, for the next 5 mins, your Pokémon within 25ft treats all difficult terrain as normal terrain, can move through enemies without slowing down, and treats vertical terrain (walls/trees/structures) as normal terrain when moving on the terrain', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 2),
  ('Harder', 'No! Not yet! Push through it! When your Pokémon hears your concern, it pushes through oncoming attacks. 1/day, when your Pokémon would be hit by an attack and the offender rolled the exact value it needed in order to hit, instead the attack misses', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 3),
  ('Makes Us Stronger', 'Everyone put everything you’ve got into it! Your enthusiasm empowers allies to push them forward. When using a Coach feature, instead of targeting just one of your Pokémon, your Coach features affect all allied Pokémon', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 4),
  ('Surf It', 'This is nothing! It’s just water! Your careful training has enabled your Pokémon’s movement both in and out of water. Your Pokémon are not hindered by movement through special terrain (water), and your Flopper Pokémon who move at half speed out of water are able to move at a normal speed out of water', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 6),
  ('Make It Better', 'Great job! Rest up, we’re not done! Quick aid keeps your Pokémon in top shape for more competition. 1/day, after a battle, pokéathalon, or contest, you can spend 5 mins with your Pokémon to recover half of the hit points they lost during the combat or competition while also giving them the ability to perform 3/day and 1/day frequency moves again', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 7),
  ('Hour After Hour', 'Keep up with me! We’re not done yet! Repeated work out sessions with your Pokémon maintains them in top shape, ready for anything. As long as your Pokémon spend at least three days every week working out with you, for at least an hour per session, they have +1 to your choice of Attack, Special Attack, or Speed while you continue to exercise with them. Pokémon can all be working out together at the same time, but no more than six Pokémon can benefit from your Hour After Hour feature at a time', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 8),
  ('Bring It', 'Come on! Imagine how hard it is for our Pokémon! Do not stop! You’ve got your whole group of friends going. By maintaining a routine of working with you for an hour each day, at least three days per week, your friends can gain an enhanced physique. They must maintain the routine for at least two weeks, and lose their benefits if they do not work out at least three days per week. They can work out together with your Pokémon through Hour After Hour, but no more than six trainers can benefit from your Bring It feature at a time. Trainers who maintain the routine can pick two of the following options to earn through exercise: move +10 feet per round of combat; Speed is +2 when determining turn order in combat; easily lift your own weight; you are not hindered by difficult terrain; you can climb and swim at normal speed', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 10),
  ('Never Over', 'That’s weak! It’s nothing compared to your strength! Let’s go! Your Pokémon know what your expectations are and they’re holding on for you. As long as they haven’t acted, your Pokémon can give up their turns during a round to survive an attack at 1 hit point if they were at their max hit points before being attacked', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 11),
  ('Face to Face', 'Don’t let them get a lead on you! Get there! Your Pokémon can edge out a little more steam when facing a near-match. When determining turn order, if there is a tie, your Pokémon go first. In addition, once per day, if once of your Pokémon misses an attack by 1 or 2, you can have them successfully hit instead', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 12),
  ('More Than Ever', 'This is what it’s all been for! Don’t any of you give up! Keep on pushing until the very end! Any Pokémon or allied trainers currently benefitting from your Hour After Hour or Bring It features get to reroll their first natural 1 per day. In addition, during appeals in contests, your Pokémon currently benefitting from your Hour After Hour feature treat any rolled 1s as 2', (select class_id from subclasses where name = 'Coach'), (select id from subclasses where name = 'Coach'), 13),

  ('Accessorize', 'With love and a flair of style you create an amazing accessory to beautify your Pokémon. After one hour of work, you create a Pokémon accessory -- a piece of clothing, jewelry, or a trinket it holds. Call it whatever you’d like, made out of whatever you’d like. It takes you one hour to repair any broken item or accessory made by you. Once per day, during an appeal of a contest, the accessory adds 1d4. If the result of that d4 is a 3 or 4, the accessory cannot be used this way again unless repaired with the Accessorize feature. A Pokémon can only benefit from one accessory at a time', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 1),
  ('Practical Designer', 'Creating a perfect something that just makes someone’s look pop can help a person succeed when they least expect it. After one hour of work, you create a trainer accessory -- a piece of clothing, jewelry, or a trinket someone holds. Call it whatever you’d like, made out of whatever you like. In addition, you are skilled in making clothing for trainers and can produce a shirt, pants, or dress in about 3 hours out of appropriate materials. Whenever you roll a Skill Check while talking to someone else, you may add +2 to your roll from the Trainer Accessory. If your skill check succeeds, the Trainer Accessory cannot be used this way again unless repaired with the Accessorize feature. A person can only benefit from one trainer accessory at a time', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 1),
  ('Lucky Charm', 'Something about the perfect charm on your wrist, or in your hair, or wherever you think someone should place it, just clicks and makes someone’s personality really come out. After two hours of work, you create a Lucky Charm -- a piece of jewelry, or a trinket you wear. Call it whatever you’d like, made out of whatever you like. Whenever you roll a Skill Check and fail, you may reroll and use the second result. If you fail again, you fumble in some way and lose 1d10 hit points. The Lucky Charm cannot be used this way again unless repaired with the Accessorize feature. A person can only benefit from one lucky charm at a time', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 2),
  ('Bright Charm', 'You focus your efforts on an accessory with some kind of gimmick; mundane at first, but with the flick of a wrist a pop of confetti or a flash of smoke appears. After one hour of work, you create a Bright Pokémon Accessory -- a piece of clothing, jewelry, or a trinket it holds. Call it whatever you’d like, made out of whatever you like. Before you appeal to a judge you may use the Bright Charm to raise the judge’s voltage +1. The Bright Charm cannot be used this way again unless repaired with the Accessorize feature. A Pokémon can only benefit from one accessory at a time', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 3),
  ('Tactical Design', 'It’s not always about looks, but when you do need a glove for climbing or a shoe for running, you can make it and make it look good. After six hours of work you create a clothing equipment for a trainer that has a specific application (running shoes, grip gloves, camouflage cape, etc.). Call it whatever you’d like, made out of whatever you like. Whenever you roll a Skill Check while doing the activity the equipment is made for, you may add +1 to your roll. The equipment loses this ability after two weeks but can be repaired with the Accessorize feature. A person can only benefit from one clothing equipment at a time', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 4),
  ('The Look', 'Sometimes, you just have to take another person’s design and make it your own. By looking at what someone else is currently wearing you’re able to make the same clothing out of the same material, adjusted for whomever you’re planning to have wear the clothing. It would take 2 hours of work per piece of clothing/accessory to replicate the what the person was wearing when you saw them but cannot replicate any other special properties of the copied outfit. You may apply effects of your Designer features to any individual piece of clothing or accessory throughout the set of things that you are copying. Unskilled individuals cannot determine whether or not your products are an original or a fake', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 6),
  ('Glamourous', 'Bold fashion statements can catch the eyes of everyone and it makes it hard not to catch everyone’s gaze when you’re the designer. When making clothing for trainers, you may spend an extra hour making the clothing to give the clothing the following effect: “All non-allied trainer’s Perception and Investigate Skill checks are -1 when you are within their line of sight.”', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 7),
  ('Cosplay Designer', 'It’s not always practical, but you’re an amazing costume designer. You can spend 30 hours over multiple days to create a medium or smaller Pokémon costume that passes for a real Pokémon unless investigated at a distance of less than 10ft. You may make it out of whatever you’d like, but the cheaper your materials, the more likely it is for someone else to recognize the costume as a costume. If you spend over 100 hours on making your costume, it is very difficult to tell that a person inside the costume is not whatever the costume is disguising them as -- at any distance', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 8),
  ('Flawless Accessory', 'With more love and a greater flair of style you create a perfect accessory to beautify your Pokémon. After two hours of work, you create a perfect Pokémon accessory -- a piece of clothing, jewelry, or a trinket it holds. Call it whatever you’d like, made out of whatever you like. 3/day, during any appeal of a contest, the accessory adds 1d4. If the result of that d4 is a 3 or 4, the Accessory cannot be used anymore during this contest. A Pokémon can only benefit from one accessory at a time', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 10),
  ('Item Builder', 'You’ve spent hours working to figure out how the battle accessories manufactured by professional companies work and you’ve figured a few of them out. Once per week, you may spend eight hours working to build one of the following items: Destiny Knot, Elemental Plate, Expert Belt, Focus Band, Focus Sash, King’s Rock, Muscle Band, Quick Claw, Razor Claw, Terrain Seeds, Weather Rocks, Terrain Extender, Shell Bell, or Wise Glasses. The items made with Item Builder need one hour of your maintenance per two weeks, otherwise they break. Call it whatever you’d like, made out of whatever you like', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 11),
  ('Item Manufacturer', 'After working to build so of your own, you’ve figured out the rest and can create your own arsenal of items of your Pokémon’s use. Once per week, you may spend eight hours working to build one of the following items: Air Balloon, Absorb Bulb, Adrenaline Orb, Assault Vest, Big Root, Binding Band, Black Sludge, Cell Battery, Choice Band, Choice Scarf, Choice Specs, Eviolite, Heavy Duty Boots, Life Orb, Protective Pads, Rocky Helmet, or Safety Goggles. The items made with Item Manufacturer need one hour of your maintenance per two weeks, otherwise they break. Call it whatever you’d like, made out of whatever you like', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 12),
  ('Endless Versatility', 'Accessories, items, clothing -- it doesn’t matter; you’ve got a creative itch and you’re ready to make it all. When making something with your Designer features, you only take 3/4ths of the time to produce whatever it is you’re making. In addition, you can alter the effects of the items you make with the Item Builder and Item Manufacturer features by changing any Pokémon type word, or stat word (for example you could make a Black Sludge item work with Fairy types instead, or make an Absorb Bulb activate on a Fire-type attack, then raise Speed). In addition, you can use your Cosplay Designer feature to create costumes of other people you have seen before (pictures work if you have views of their front, sides, and back). In addition, you may make held items with your features that affect trainers instead of Pokémon that are all one-time use items', (select class_id from subclasses where name = 'Designer'), (select id from subclasses where name = 'Designer'), 13),

  ('Expert Grooming', 'It’s a groomer’s duty to keep their Pokémon’s fur fluffy, feathers dusted, or scales shined. You can spend fifteen mins with one of your Pokémon to give them an Expert Grooming. After the grooming they are relaxed unless they are agitated again, you can emphasize and polish their physical appearance, making them appear to be healthy, sick, or any other physical state within normal variation for their species. Your Pokémon quickly gain loyalty to you if you’re grooming them often and are very unlikely to lose loyalty unless there’s any intentional mistreatment', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 1),
  ('Pokémon Whisperer', 'Humans are rarely inclined to start a fight while already in conversation, and neither are Pokémon. After speaking in a calm tone to a Pokémon for at least ten seconds, that Pokémon will refrain from attacking as long as you continue speaking, you and your allies do not approach them or initiate combat, and there is no clear threat to them. If you are already physically but nonviolently handling them as you begin speaking with them, they will allow you to continue to handle them or use your Groomer features on them', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 1),
  ('Touch Up', 'With some quick snips, brushing, and balms you fix up your Pokémon. 3/day, after spending a minute grooming a Pokémon, choose two of the following benefits for that Pokémon (you must choose different options): restore a single use of a Pokémon’s 3/day move; heal 4 HP; +2 to Attack, Special Attack, or Speed for ten minutes, or until they take damage, whichever comes first; the first two rolled 1s during contest appeals can be rerolled during the next contest on the same day', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 2),
  ('Groomer’s Eye', 'By working with Pokémon to make them look the best they can all the time, you have insight into a Pokémon''s needs when you’re working with them. When making Pokémon Handling checks you can roll twice and use the better result. If you’re grooming or pacifying a Pokémon as you do this, roll three times and use the best result instead. In addition, while grooming a Pokémon, you can determine any stressors that the Pokémon is dealing with (maltreatment, hunger, sickness, etc.), whether or not it is loyal to its trainer, any special traits of its parentage or birth environment, any special needs it may have', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 3),
  ('Contest Coating', 'They’re just too much to look at! They’re so amazingly over the top! Your special care really gives your Pokémon an edge during Contests. Your Pokémon can have up to 12 points total contest stats. In addition, loyal Pokémon you’ve had for at least one week that have been cared for with Expert Grooming do not take a penalty to their stat because of their nature', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 4),
  ('Quick Cleanse', 'Some Pokémon need special attention to take care of a particularly bad day battling and with careful grooming, you’ve got them covered. 3/day, as an action, you can cure a Pokémon of any afflictions, remove any lingering negative stat effects, or prevent the next affliction the Pokémon would receive that day', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 6),
  ('Attribution Assistance', 'All this grooming is supposed to be for showing off a contest, so you’ve begun to focus on what makes a Pokémon pop in a stricter contest setting. Once per day, while Expert Grooming, you may add 1 point to any of the Pokémon’s contest stats, but cannot raise any of their contest stats to a value higher than whichever is the higher value between your Special Defense and Speed stats with this ability', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 7),
  ('Glossy Alteration', 'These makeover looks are stunning and have a functional form. 1/day, while Expert Grooming a loyal Pokémon, you may have the groomed Pokémon gain one of the following Passives or Skills: Immunity (immune to getting Poisoned and Toxified), Limber (immune to being Paralyzed), Magma Armor (immune to being Frozen), Vital Spirit (immune to being put to Sleep), or Water Veil (immune to being Burned); or the Skills Alluring (attracts others with their appearance), Glow (can produce light), Repulsive (repels others with their appearance), or Stealth (can make stealth skill checks). Each of your Pokémon cannot have more than one passive and/or skill granted by Glossy Alteration at a time', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 8),
  ('Groundbreaking Makeover', 'It’s unorthodox, it’s wild, it’s insane but you’ve figured it out and you’ve got the perfect customers -- your lovely Pokémon! Once per week, after spending 10 hours working on one of your loyal Pokémon, they become a shiny Pokémon. Choose any color for them to permanently become in whatever pattern you’d like. In addition, during introductory appeals in contests, your shiny Pokémon adds 2d4 to their initial appeal and can replace any of their move’s contest effects with the Attention Grabber or Special Attention effect once per contest', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 10),
  ('Head Turner', 'It’s not your expertise, but why not dive into the world of trainer haircuts and styling? You can spend fifteen mins with another trainer to give them a makeover. If you change the trainer’s hair style, hair color, or general amount of make up they might use, it’s possible that they won’t be immediately recognizable. When made over, trainers making Bluff or Diplomacy skill checks within the first 12 hours of your makeover get +1 on their skill check on their first skill check per person they interact with. You may make yourself over, but it takes thirty mins to use Head Turner instead', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 11),
  ('Secured Style', 'The contest stage is a battlefield, just as much as the battlefield is a performance stage, and with your beautification, your Pokémon are ready for anything! 1/day, after Expert Grooming a loyal Pokémon raise its Defense or Special Defense by 2 for 3 hours. Additionally, the Pokémon can ignore the contest effect of one move performed by an opponent during a contest that would affect when your Pokémon performs during appeals, or prevents voltage manipulation of some kind', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 12),
  ('Elite Glamour', 'Untouchable beauty for any Pokémon in ten to fifteen minutes. 1/day, after Expert Grooming a loyal Pokémon, they may give them an Elite Coat. The Coat has the following ability: the first time you take damage from an attack, halve the damage. This coat lasts for 12 hours and does not disappear when a Pokémon with the Elite Coat is returned to a Poké Ball', (select class_id from subclasses where name = 'Groomer'), (select id from subclasses where name = 'Groomer'), 13),

  ('Incognito', 'You chose the path of fame and maintain an online presence that garners thousands if not hundreds of thousands of followers, so it’s a good skill to be able to lay low. When you want to, you can change your clothes or style in some way to become uninteresting. While uninteresting, it’s much harder for others to notice what you’re doing and your Stealth and Sleight of Hand Skills are +2, however your Bluff, Insight, and Diplomacy Skills are all -2', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 1),
  ('Influencer', 'There’s very little stopping you from getting what you want, just by standing by something or somewhere, others will want to be there buying those things, too. When purchasing items for yourself or your Pokémon, you will get a discount depending on the size of the store or other place of service. A small mom and pop shop will not give you that much of a discount but larger conglomerate stores will give you more generous discounts and even gifts. While all stores are obligated to give you discounts, be aware that any pushy behavior may result in unwelcome behavior from the store’s employees', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 1),
  ('Golden Cheer', 'Your exuberance raises the mood of your allies and helps them to succeed whenever you’re cheering them on. Once per day, when an ally makes an attack, or attempts a skill check, they may roll twice and use the better result. If the attack or skill check already is making two or more rolls, add another roll and use the best result', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 2),
  ('Autographs and Selfies', 'When you want to flaunt it and catch everyone’s attention, you’re usually able to cause quite a scene by announcing your presence. As long as you are in a region where your fame is known (at least 3 ribbons and/or badges) you can announce your presence and cause a distraction. Non-allied trainers nearby are compelled to either join you, asking for your autograph or a photo with you, or are just distracted by the spectacle of your showmanship. If anyone becomes distracted by something other than you, or are otherwise alerted, they will stop whatever it is they were doing with you earlier than normal, if not immediately', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 3),
  ('Garnered Loyalty', 'Your Pokémon love you and if they don’t, they are really easy to win over. Your Pokémon with under 4 loyalty, rapidly gain loyalty. It takes no more than 24 hours to raise one of your Pokémon’s loyalty one stage if they are at loyalty 0, 1, or 2 unless they are already at 2 loyalty. It takes intentional and malicious mistreatment to lower your Pokémon’s loyalties', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 4),
  ('Seat of Celebrity', 'Once well known in your expertise, you dominate the personalities in your sphere of influence and others will often go out of their way to make a mutually beneficial deal go through. Depending on the base classes you have, you gain some of the following options -- these trainers will likely join you even if they’ve never met you before (it is possible to lose access to the coordinator option): Ace Trainer -- you may call upon regionally famous gym leaders, elites, brains or any other famous and powerful trainers to aid you in your efforts in a competition or just for an exhibition match. Breeder -- you have access to a regional list of breeders for rare or expensive Pokémon species and can arrange appointments free of charge for your Pokémon to produce eggs with any regionally available Pokémon. Coordinator (only) -- as an exclusive coordinator, you have woven your ties in deep throughout your regional community; when joining a contest, you are made aware of any judges and you know what at least one Star Point category is per judge. Ranger -- you have access to the captains of the regional ranger union, and can call upon their personal help in any dangerous situations or use your influence to rally many civilians to aid in ranger efforts with little trouble. Researcher -- you have access to any regional professors and doctors who will meet with you, plan joint research endeavors, and even research things for you (within reason) free of charge', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 6),
  ('Stirring Speech', 'When you lead a positively powerful speech, you encourage everyone to get up and finish what they started. Once per day, you may spend 3 mins encouraging your allies. All allies, trainer and Pokémon alike, are healed of any afflictions, then at the start of their next combat encounter, they gain 5 temporary hit points', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 7),
  ('On the List', 'By virtue of being who you are, most people will believe you are supposed to be where you say you’re supposed to be, doing what you say you’re supposed to be doing. When making a Bluff skill check, you may roll three times and use the best result. As long as your perform well enough on your skill check, only a person in charge of an entire organization might disagree with your behavior and expose you', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 8),
  ('Platinum Cheer', 'You raise a wild energy around you when cheering on your friends’ efforts, making them believe anything is possible! Once per day, as an action, you give an energetic cheer that empowers all allies. For 10 mins, all allies deal +X damage when attacking, all allied skill checks add +2 to their roll, all skill checks made against your allies are -2 during their roll, and all allies recover X hit points, then gain X temporary hit points. X is equal to your Special Defense or Speed modifier', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 10),
  ('Disheartening Blow', 'It’s very unkind and probably beneath you but your presence can be demoralizing when you pair it with a nasty insult. 3/day you may use Vicious Insult', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 11),
  ('Empowering Aid', 'Your friends are amazing and your friendships are supportive and powerful. When making a skill check, one of your allies can use an action to add their highest modifier to your skill check. When an ally is making a skill check, you may use an action to add your Special Defense or Speed modifier +3 to their skill check', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 12),
  ('Preposterous Wealth', 'You’re on top of the world and have many fanatic followers from all over the planet. Your wealth is a non-issue due to your countless endorsements and sponsorships so if something is sold somewhere, you can afford it. The limitations of what you’re allowed to obtain/purchase is any kind of Pokémon that are in some way unusual due to being shiny, a strange typing, or having some other oddity about them. You also cannot buy something that is not for sale, for example if a Master Ball is not being sold because it’s a prototype, a collection piece, or out of stock you wouldn’t be able to buy it. Even then, if someone is selling a shiny Pokémon, you pay them and can have it or could commission a talented smith to create a Master Ball over time. In addition, any Rising Star feature that is limited by regional fame is now expanded to a global range', (select class_id from subclasses where name = 'Rising star'), (select id from subclasses where name = 'Rising star'), 13);
